	local function startJaneAnchor(dummy)
		if janeAnchorConn then
			janeAnchorConn:Disconnect()
			janeAnchorConn = nil
		end
		if not dummy then return end
		local dRoot = dummy:FindFirstChild("HumanoidRootPart") or dummy:FindFirstChild("Torso")
		if not dRoot then return end
		dummy.PrimaryPart = dRoot
		janeAnchorConn = RunService.Heartbeat:Connect(function()
			if not dummy or not dummy.Parent then
				if janeAnchorConn then
					janeAnchorConn:Disconnect()
					janeAnchorConn = nil
				end
				return
			end
			local myRoot = figureRef and (
				figureRef:FindFirstChild("HumanoidRootPart") or
				figureRef:FindFirstChild("Torso")
			)
			if myRoot then
				dummy:PivotTo(myRoot.CFrame * CFrame.new(0, -9, 0))
			end
		end)
	end

	local function stopJaneAnchor()
		if janeAnchorConn then
			janeAnchorConn:Disconnect()
			janeAnchorConn = nil
		end
	end

	local function setupFlingTouched(figure)
		local function hookPart(part)
			local conn = part.Touched:Connect(function(hit)
				if not hit or not hit.Parent then return end
				local target = hit.Parent
				if target:IsA("Accessory") then target = target.Parent end
				if target == figure then return end
				if not target:FindFirstChildOfClass("Humanoid") then return end
				if flingActive then
					ReanimateFling(target)
				end
			end)
			table.insert(touchConns, conn)
		end
		for _, part in ipairs(figure:GetDescendants()) do
			if part:IsA("BasePart") then hookPart(part) end
		end
		table.insert(touchConns, figure.DescendantAdded:Connect(function(part)
			if part:IsA("BasePart") then hookPart(part) end
		end))
	end

	
