	local function spawnVictimNPC(victimName, targetPlayer, offsetCFrame, animName, duration)
		if not figureRef then return end
		local dummy

		
		if targetPlayer and targetPlayer.Character then
			pcall(function()
				targetPlayer.Character.Archivable = true
				dummy = targetPlayer.Character:Clone()
				targetPlayer.Character.Archivable = false
			end)
		end

		
		if not dummy then
			pcall(function()
				figureRef.Archivable = true
				dummy = figureRef:Clone()
				figureRef.Archivable = false
			end)
		end

		
		if not dummy then
			pcall(function()
				dummy = Players:CreateHumanoidModelFromDescription(
					Instance.new("HumanoidDescription"),
					Enum.HumanoidRigType.R6
				)
			end)
		end
		if not dummy then return nil end

		dummy.Name   = victimName
		dummy.Parent = workspace

		
		
		for _, v in ipairs(dummy:GetDescendants()) do
			if v:IsA("Script") or v:IsA("LocalScript") or v:IsA("Sound")
			or v:IsA("ScreenGui") or v:IsA("BillboardGui") or v:IsA("SurfaceGui") then
				v:Destroy()
			elseif v:IsA("BasePart") then
				v.Massless   = true
				v.CanCollide = false
				v.CanTouch   = false
				v.CanQuery   = false
				
				v.Anchored   = (v.Name == "HumanoidRootPart")
			end
		end

		local myRoot = figureRef:FindFirstChild("HumanoidRootPart")
			or figureRef:FindFirstChild("Torso")
		local dRoot  = dummy:FindFirstChild("HumanoidRootPart")
			or dummy:FindFirstChild("Torso")
		if myRoot and dRoot then
			dummy.PrimaryPart = dRoot
			dummy:PivotTo(myRoot.CFrame * offsetCFrame)
		end

		local ok, dAnim = pcall(function()
			return loadAnim(dummy, animName, false)
		end)
		if ok and dAnim then
			dAnim.weight = 1
			table.insert(activeVictims, {
				anim  = dAnim,
				dummy = dummy,
				start = os.clock(),   
			})
		end
		Debris:AddItem(dummy, duration + 0.5)
		return dummy
	end

	
	local function getRandomPlayer()
		local valid = {}
