		ContextActions:SetTitle("doe_outro",     "Outro")
		ContextActions:SetTitle("doe_sprint",    "Sprint")

		ContextActions:SetPosition("doe_m1",        UDim2.new(1,-70,  1,-70))
		ContextActions:SetPosition("doe_corrupt",   UDim2.new(1,-140, 1,-70))
		ContextActions:SetPosition("doe_kill",      UDim2.new(1,-210, 1,-70))
		ContextActions:SetPosition("doe_footprint",    UDim2.new(1,-280, 1,-70))
      ContextActions:SetPosition("doe_sprint", UDim2.new(1, -350, 1, -70))
		ContextActions:SetPosition("doe_intro",     UDim2.new(1,-70,  1,-150))
		ContextActions:SetPosition("doe_jane_kill", UDim2.new(1,-140, 1,-150))
		ContextActions:SetPosition("doe_stun",      UDim2.new(1,-210, 1,-150))
		ContextActions:SetPosition("doe_error",     UDim2.new(1,-280, 1,-150))
		ContextActions:SetPosition("doe_outro",     UDim2.new(1,-350, 1,-150))
	end

	m.Update = function(dt, figure)
		if not animator then return end
		local hum = figure:FindFirstChildOfClass("Humanoid")
		if not hum then return end

		
		local now = os.clock()
		for i = #activeVictims, 1, -1 do
			local data = activeVictims[i]
			if data.dummy and data.dummy.Parent then
				data.anim:Step(now - data.start)
			else
				table.remove(activeVictims, i)
			end
		end

		
		if not usingSkill then
			local state = "idle"
			if hum.MoveDirection.Magnitude > 0.1 then
				state = isSprinting and "run" or "walk"
			end

			if lastState ~= state then
				animationTime = 0
				lastState     = state
			end

			local newTrack
			if state == "idle" then
				newTrack = tracks.idle
				hum.WalkSpeed = errorSlowActive and errorSlowSpeed or 8
			elseif state == "walk" then
				newTrack = tracks.walk
				hum.WalkSpeed = errorSlowActive and errorSlowSpeed or 8
			elseif state == "run" then
				newTrack = tracks.run
				hum.WalkSpeed = errorSlowActive and errorSlowSpeed or 27.5
			end

			
			if lowerAnimator and newTrack and lowerAnimator.track ~= newTrack then
				lowerAnimator.track  = newTrack
				lowerAnimator.looped = true
			end

			
			if not isM1Active then
				if currentTrack ~= newTrack then
					currentTrack   = newTrack
					animator.track = currentTrack
				end
			end
		end

		animationTime += dt

		if isM1Active then
			
			
			
			local LEG_JOINTS = {
				["Left Hip"]  = true,
				["Right Hip"] = true,
			}

			if lowerAnimator then
				
				lowerAnimator.looped = true
				lowerAnimator:Step(animationTime)

				
				local legSnapshot = {}
				for _, motor in ipairs(figure:GetDescendants()) do
					if motor:IsA("Motor6D") and LEG_JOINTS[motor.Name] then
						legSnapshot[motor] = motor.Transform
					end
				end

				
				m1AnimTime += dt
				animator.looped = false
				animator:Step(m1AnimTime)

				
				
				for motor, cf in pairs(legSnapshot) do
					motor.Transform = cf
				end
			else
				
				m1AnimTime += dt
				animator.looped = false
				animator:Step(m1AnimTime)
			end
		else
			
			if usingSkill then
				
				animator:Step(animationTime)
			else
				animator.looped = true
				animator:Step(animationTime)
			end
		end
	end

	m.Destroy = function()
		idleVoiceActive = false
		isSprinting     = false
		flingActive     = false
		usingSkill      = false
		errorSlowActive = false
		for _, conn in ipairs(touchConns) do conn:Disconnect() end
		table.clear(touchConns)
		for _, data in ipairs(activeVictims) do
			if data.dummy then data.dummy:Destroy() end
		end
		activeVictims = {}
		
		ContextActions:UnbindAction("doe_m1")
		ContextActions:UnbindAction("doe_corrupt")
		ContextActions:UnbindAction("doe_kill")
		ContextActions:UnbindAction("doe_intro")
		ContextActions:UnbindAction("doe_jane_kill")
		ContextActions:UnbindAction("doe_stun")
		ContextActions:UnbindAction("doe_error")
		ContextActions:UnbindAction("doe_footprint")
		ContextActions:UnbindAction("doe_outro")
		ContextActions:UnbindAction("doe_sprint")
		isM1Active    = false
		m1AnimTime    = 0
		lowerAnimator = nil
		animator      = nil
		tracks        = {}
		currentTrack  = nil
		figureRef     = nil
	end

	return m
end)
return modules

end)
if not ok then
    (warn or print)("[KernelPacker] failed to load John reanimate.lua: " .. tostring(result))
elseif type(result) == "table" and result ~= modules then
    for _, fn in ipairs(result) do table.insert(modules, fn) end
end
end

return modules
